// AVTOMATIK GENERATSIYA QILINGAN KATALOG — TEXNO BOZOR
// Ilova birinchi ochilganda SQLite bazasiga yoziladi (offline-first).

import 'dart:convert';

import 'package:sqflite/sqflite.dart';

/// Katalog seed ma'lumotlari: kategoriyalar, mahsulotlar va sharhlar.
class SeedData {
  const SeedData._();

  /// Bazaga boshlang'ich katalogni yozadi.
  static Future<void> populate(Database db) async {
    final now = DateTime.now().millisecondsSinceEpoch;
    const day = 86400000;
    final batch = db.batch();

    for (final c in categories) {
      batch.insert('categories', c, conflictAlgorithm: ConflictAlgorithm.replace);
    }

    final categoryImages = {
      for (final c in categories) '${c['id']}': '${c['image']}',
    };

    for (final p in _rawProducts) {
      final days = p[11] as int;
      batch.insert('products', {
        'id': p[0],
        'name': p[1],
        'brand': p[2],
        'category_id': p[3],
        'price': p[4],
        'old_price': p[5],
        'rating': p[6],
        'rating_count': p[7],
        'stock': p[8],
        'description': p[9],
        'specs': jsonEncode(p[12]),
        'image': categoryImages[p[3]] ?? '',
        'popularity': p[10],
        'created_at': now - days * day,
      }, conflictAlgorithm: ConflictAlgorithm.replace);
    }

    var reviewIndex = 0;
    for (final r in _rawReviews) {
      reviewIndex++;
      batch.insert('reviews', {
        'id': 'rev-$reviewIndex',
        'product_id': r[0],
        'author': r[1],
        'rating': r[2],
        'text': r[3],
        'created_at': now - (r[4] as int) * day,
      }, conflictAlgorithm: ConflictAlgorithm.replace);
    }

    await batch.commit(noResult: true);
  }

